package com.otectus.immersivejewelry.minigame.cutting;

import com.otectus.immersivejewelry.data.cut.CutPattern;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.util.Mth;

import java.util.Random;

/**
 * Everything the cutting simulation needs, generated by the server from the stone, the cut, the lap and the config,
 * and sent to the client whole (so both sides run identical numbers).
 *
 * @param angles       facet centre angles (radians)
 * @param halfWidths   angular half-width of each facet's contact region
 * @param windowCenter target depth of each facet (0..1)
 * @param windowHalf   half-width of the depth window
 * @param order        facet indices in the order they are worked
 * @param innerRadius  contact regions start at this radius (the table inside is not a facet)
 * @param drift        wobble amplitude of the contact point
 * @param freqs        four wobble frequencies (radians per second)
 * @param phases       four wobble phases
 * @param grindRate    facet depth per second at full pressure
 * @param ramp         seconds for pressure to rise from none to full
 * @param heatRate     heat per second at full pressure
 * @param coolRate     heat shed per second while not grinding
 * @param chipThreshold heat at which the stone chips
 * @param maxSteps     session length in steps
 */
public record CutParams(CutPattern pattern, float[] angles, float[] halfWidths, float[] windowCenter, float windowHalf, int[] order,
                        float innerRadius, float drift, float[] freqs, float[] phases, float grindRate, float ramp,
                        float heatRate, float coolRate, float chipThreshold, int maxSteps) {

    /** What goes into the parameters. {@code precision}, {@code stability}, {@code speed}, {@code cooling}: the lap. */
    public record Inputs(int facets, CutPattern pattern, float cutDifficulty, float gemDifficulty, float hardness, float brittleness,
                         float inclusions, float size, float precision, float stability, float speed, float cooling,
                         float configDifficulty, boolean largerTargets, boolean slower, int secondsPerFacet) {}

    public int facets() {
        return angles.length;
    }

    public static CutParams create(Inputs in, long seed) {
        Random random = new Random(seed);
        int k = Mth.clamp(in.facets(), 2, 16);
        float difficulty = Mth.clamp(in.cutDifficulty() * in.gemDifficulty() * in.configDifficulty(), 0.2F, 4F);
        float assistWidth = in.largerTargets() ? 1.35F : 1F;
        float assistSpeed = in.slower() ? 0.72F : 1F;
        float sizeFactor = 0.85F + 0.15F * Mth.clamp(in.size(), 0.3F, 1.6F);

        float[] angles = new float[k];
        float[] half = new float[k];
        float spacing = Mth.TWO_PI / k;
        float rotation = in.pattern() == CutPattern.RADIAL ? random.nextFloat() * spacing : 0F;
        float baseHalf = spacing * 0.5F * 0.62F * in.precision() * assistWidth * sizeFactor / (float) Math.sqrt(difficulty);
        for (int i = 0; i < k; i++) {
            angles[i] = wrap(rotation + i * spacing);
            float w = baseHalf;
            if (in.pattern() == CutPattern.STEP) w *= (i % 2 == 0) ? 1.3F : 0.7F;
            if (in.pattern() == CutPattern.DOME) w *= 1.35F;
            half[i] = Math.min(w, spacing * 0.5F * 0.92F);
        }
        float[] centers = new float[k];
        for (int i = 0; i < k; i++) centers[i] = 0.78F + (random.nextFloat() - 0.5F) * 0.12F;
        float windowHalf = Mth.clamp(0.13F * in.precision() * assistWidth / (float) Math.pow(difficulty, 0.6), 0.045F, 0.22F);

        float drift = Mth.clamp(0.16F * (float) Math.sqrt(difficulty) * (0.6F + in.brittleness()) / in.stability()
                * (in.largerTargets() ? 0.75F : 1F), 0.03F, 0.42F);
        float[] freqs = new float[4];
        float[] phases = new float[4];
        for (int i = 0; i < 4; i++) {
            freqs[i] = (1.1F + random.nextFloat() * 1.6F) * assistSpeed;
            phases[i] = random.nextFloat() * Mth.TWO_PI;
        }
        float hardnessFactor = 0.6F + in.hardness() / 12F;
        float grindRate = 0.8F * in.speed() * assistSpeed / hardnessFactor;
        float heatRate = 0.5F * assistSpeed;
        float coolRate = 0.42F * in.cooling();
        float chipThreshold = Math.max(0.45F, 1F - 0.3F * in.brittleness() - 0.25F * in.inclusions());
        int maxSteps = k * Math.max(2, in.secondsPerFacet()) * 1000 / com.otectus.immersivejewelry.minigame.StepClock.STEP_MS;
        return new CutParams(in.pattern(), angles, half, centers, windowHalf, order(k, in.pattern()),
                in.pattern() == CutPattern.DOME ? 0.2F : in.pattern() == CutPattern.STEP ? 0.5F : 0.45F,
                drift, freqs, phases, grindRate, in.slower() ? 1.25F : 0.9F, heatRate, coolRate, chipThreshold, maxSteps);
    }

    /** Opposite facets in turn for radial cuts (symmetry), long sides before corners for step cuts. */
    static int[] order(int k, CutPattern pattern) {
        int[] out = new int[k];
        int n = 0;
        if (pattern == CutPattern.RADIAL && k % 2 == 0) {
            for (int i = 0; i < k / 2; i++) {
                out[n++] = i;
                out[n++] = i + k / 2;
            }
        } else if (pattern == CutPattern.STEP) {
            for (int i = 0; i < k; i += 2) out[n++] = i;
            for (int i = 1; i < k; i += 2) out[n++] = i;
        } else {
            for (int i = 0; i < k; i++) out[n++] = i;
        }
        return out;
    }

    static float wrap(float angle) {
        float a = angle % Mth.TWO_PI;
        if (a < 0) a += Mth.TWO_PI;
        return a;
    }

    public void write(FriendlyByteBuf buf) {
        buf.writeEnum(pattern);
        buf.writeVarInt(angles.length);
        for (int i = 0; i < angles.length; i++) {
            buf.writeFloat(angles[i]);
            buf.writeFloat(halfWidths[i]);
            buf.writeFloat(windowCenter[i]);
            buf.writeVarInt(order[i]);
        }
        buf.writeFloat(windowHalf);
        buf.writeFloat(innerRadius);
        buf.writeFloat(drift);
        for (int i = 0; i < 4; i++) {
            buf.writeFloat(freqs[i]);
            buf.writeFloat(phases[i]);
        }
        buf.writeFloat(grindRate);
        buf.writeFloat(ramp);
        buf.writeFloat(heatRate);
        buf.writeFloat(coolRate);
        buf.writeFloat(chipThreshold);
        buf.writeVarInt(maxSteps);
    }

    public static CutParams read(FriendlyByteBuf buf) {
        CutPattern pattern = buf.readEnum(CutPattern.class);
        int k = Mth.clamp(buf.readVarInt(), 2, 16);
        float[] angles = new float[k];
        float[] half = new float[k];
        float[] centers = new float[k];
        int[] order = new int[k];
        for (int i = 0; i < k; i++) {
            angles[i] = buf.readFloat();
            half[i] = buf.readFloat();
            centers[i] = buf.readFloat();
            order[i] = Mth.clamp(buf.readVarInt(), 0, k - 1);
        }
        float windowHalf = buf.readFloat();
        float inner = buf.readFloat();
        float drift = buf.readFloat();
        float[] freqs = new float[4];
        float[] phases = new float[4];
        for (int i = 0; i < 4; i++) {
            freqs[i] = buf.readFloat();
            phases[i] = buf.readFloat();
        }
        return new CutParams(pattern, angles, half, centers, windowHalf, order, inner, drift, freqs, phases, buf.readFloat(),
                buf.readFloat(), buf.readFloat(), buf.readFloat(), buf.readFloat(), buf.readVarInt());
    }
}
